with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'تغير المناخ وتقييم المخاطر والتكيف القطاعي','تقييم المخاطر والتعرض والهشاشة وإسناد التطرفات وتصغير الإسقاطات وتصحيح الانحياز والتكيف والتواصل المناخي.',28,false from c on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'تقييم المخاطر المناخية',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'إسقاطات المناخ ومعالجتها',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u3 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'التكيف والقرار المناخي',3,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit) as (values ('climate-risk-assessment-framework','إطار تقييم مخاطر تغير المناخ','تحليل الخطر والتعرض والهشاشة والقدرة على التكيف في السياق المناخي.','{"blocks":[{"type":"text","text":"يربط تقييم مخاطر المناخ بين الظواهر المناخية والخطر والتعرض والهشاشة والقدرة على التكيف."},{"type":"text","text":"يشير الخطر إلى احتمال وقوع ظاهرة مناخية ذات خصائص وشدة ومدة محددة."},{"type":"text","text":"يشير التعرض إلى وجود السكان أو الأصول أو النظم البيئية في مناطق يمكن أن تتأثر بالظاهرة."},{"type":"text","text":"تعبر الهشاشة عن قابلية النظام للتضرر وتتأثر بالعوامل الاجتماعية والاقتصادية والبيئية والبنية التحتية."},{"type":"text","text":"تؤثر القدرة على التكيف والاستجابة في تقليل الأضرار المتوقعة والحد من المخاطر المتبقية."},{"type":"text","text":"يجب تحديد المقياس المكاني والزمني والقطاع المستهدف قبل اختيار المؤشرات والبيانات."},{"type":"text","text":"تستخدم السجلات التاريخية والإسقاطات المناخية وخرائط التعرض والبيانات الاجتماعية والاقتصادية معاً."},{"type":"text","text":"قد تختلف المخاطر بين منطقتين تتعرضان للظاهرة نفسها بسبب اختلاف الهشاشة والجاهزية."},{"type":"text","text":"يجب توثيق مصادر البيانات والافتراضات وعدم اليقين وحدود المقارنة."},{"type":"text","text":"تساعد سيناريوهات متعددة على اختبار حساسية النتائج لتغير المناخ والتطور الاجتماعي والاقتصادي."},{"type":"text","text":"مثال: موجة حر واحدة قد تشكل خطراً أكبر في منطقة حضرية ذات كثافة عالية وخدمات تبريد محدودة."},{"type":"callout","text":"خلاصة: تقييم المخاطر المناخية يجمع العلم الطبيعي والبيانات المكانية والظروف الاجتماعية والقدرة على الاستجابة."}]}',2060,60,'["شرح مكونات المخاطر المناخية","تمييز الخطر عن التعرض والهشاشة","بناء تقييم متعدد القطاعات"]','تقييم المخاطر المناخية'),
('climate-exposure-vulnerability-indicators','مؤشرات التعرض والهشاشة والقدرة على التكيف','اختيار المؤشرات وبناء خرائط الأولوية وتفسير الفروق المكانية.','{"blocks":[{"type":"text","text":"تستخدم مؤشرات التعرض والهشاشة لتحديد المناطق والفئات التي قد تتأثر بصورة أكبر بالمخاطر المناخية."},{"type":"text","text":"قد تشمل مؤشرات التعرض الكثافة السكانية ومواقع البنية التحتية والأراضي الزراعية ومصادر المياه."},{"type":"text","text":"قد تشمل مؤشرات الهشاشة الاعتماد الاقتصادي والحساسية الصحية وجودة المساكن والموارد المتاحة."},{"type":"text","text":"تشمل مؤشرات القدرة على التكيف الوصول إلى المعلومات والموارد والخدمات والبنية المؤسسية."},{"type":"text","text":"تحتاج المؤشرات إلى تعريفات واضحة ومصادر موثوقة وفترات مرجعية متسقة."},{"type":"text","text":"تختلف وحدات القياس، ولذلك قد تحتاج البيانات إلى تطبيع قبل دمجها في مؤشر مركب."},{"type":"text","text":"يؤثر اختيار الأوزان وطريقة التجميع في ترتيب المناطق، ويجب توثيق الأساس المستخدم."},{"type":"text","text":"قد يخفي المؤشر المركب فروقاً مهمة بين مكوناته، لذلك ينبغي عرض القيم التفصيلية بجانبه."},{"type":"text","text":"تحتاج خرائط الأولوية إلى التحقق الميداني ومراجعة أصحاب المصلحة والجهات المحلية."},{"type":"text","text":"يجب تجنب تفسير المؤشر كحقيقة مطلقة أو كترتيب ثابت خارج فترة البيانات المستخدمة."},{"type":"text","text":"مثال: قد تظهر منطقة ذات تعرض مرتفع لكنها تمتلك قدرة استجابة أفضل من منطقة أقل تعرضاً وأكثر هشاشة."},{"type":"callout","text":"خلاصة: المؤشرات أدوات مساعدة للقرار، وتعتمد قيمتها على الشفافية والتعريف والبيانات."}]}',2070,60,'["اختيار مؤشرات مناسبة","توحيد المقاييس والبيانات","فهم حدود المؤشرات المركبة"]','تقييم المخاطر المناخية'),
('extreme-event-attribution','إسناد الأحداث المناخية المتطرفة وتفسير دور تغير المناخ','مقارنة العالم الفعلي بعوالم افتراضية وتقدير تغير الاحتمال والشدة.','{"blocks":[{"type":"text","text":"يبحث إسناد الأحداث المتطرفة في كيفية تغير احتمال الحدث أو شدته في ظل تأثير العوامل البشرية والمناخية."},{"type":"text","text":"يقارن التحليل عادة مناخ العالم الفعلي بمناخ افتراضي لا يتضمن بعض التأثيرات البشرية، وفق تصميم الدراسة."},{"type":"text","text":"قد يقدر الإسناد تغير احتمال تجاوز عتبة حرارية أو مطرية، أو تغير شدة الحدث عند احتمال محدد."},{"type":"text","text":"يتطلب التحليل تعريف الحدث والعتبة والمنطقة والفترة بدقة قبل بناء المقارنة."},{"type":"text","text":"تستخدم سجلات الرصد والنماذج المناخية والتحليل الإحصائي لتقدير التوزيعات والاحتمالات."},{"type":"text","text":"يجب تقييم قدرة النماذج على تمثيل الظاهرة والمنطقة قبل استخدامها في دراسة الإسناد."},{"type":"text","text":"قد تكون بعض الأحداث أكثر قابلية للإسناد من غيرها بسبب طبيعتها ومحدودية السجلات أو تعقيد الآليات."},{"type":"text","text":"لا يعني الإسناد أن تغير المناخ هو السبب الوحيد لحدث بعينه؛ بل يقدر أثره على الاحتمال أو الشدة ضمن إطار محدد."},{"type":"text","text":"تختلف النتائج باختلاف تعريف الحدث والفترة المرجعية ومجموعة النماذج وطريقة التحليل."},{"type":"text","text":"ينبغي شرح عدم اليقين وحدود الدراسة وعدم تعميمها خارج نطاقها المكاني والزمني."},{"type":"text","text":"مثال: قد تشير دراسة إلى زيادة احتمال موجة حر مماثلة في المناخ الحالي مقارنة بمناخ سابق، دون أن تعني أن كل موجة حر سببها عامل واحد."},{"type":"callout","text":"خلاصة: إسناد التطرفات تحليل احتمالي مقارن يحتاج تعريفاً واضحاً ونماذج مقيمة وتفسيراً حذراً."}]}',2080,60,'["شرح مفهوم إسناد الحدث","تمييز الاحتمال والشدة","فهم حدود الدراسات الإسنادية"]','تحليل التطرفات والإسناد'),
('climate-downscaling-methods','طرق التصغير المكاني للإسقاطات المناخية','التصغير الديناميكي والإحصائي وتحويل المخرجات العالمية إلى معلومات إقليمية.','{"blocks":[{"type":"text","text":"تنتج النماذج المناخية العالمية مخرجات على شبكات لا تمثل دائماً التفاصيل المحلية المطلوبة للتخطيط."},{"type":"text","text":"يهدف التصغير المكاني إلى توفير معلومات أدق عن التباين الإقليمي والمحلي ضمن حدود البيانات والنموذج."},{"type":"text","text":"يستخدم التصغير الديناميكي نموذجاً إقليمياً عالي الدقة داخل مجال محدود مع شروط حدية من نموذج أكبر."},{"type":"text","text":"يستخدم التصغير الإحصائي علاقات تاريخية بين المتغيرات واسعة النطاق والقياسات المحلية."},{"type":"text","text":"تتطلب الطرق الإحصائية سجلات طويلة ومتجانسة وتمثيلاً جيداً للأنماط المناخية المؤثرة."},{"type":"text","text":"قد يفشل التصغير الإحصائي إذا تغيرت العلاقات بين المتغيرات أو ظهرت ظروف خارج نطاق التدريب."},{"type":"text","text":"يتطلب التصغير الديناميكي موارد حسابية واختيارات مناسبة للفيزياء والتضاريس والشروط الحدية."},{"type":"text","text":"لا يزيل التصغير عدم اليقين في السيناريوهات أو النماذج أو الحالة المناخية المستقبلية."},{"type":"text","text":"يجب تقييم قدرة طريقة التصغير على إعادة إنتاج المناخ التاريخي قبل استخدامها في الإسقاطات."},{"type":"text","text":"ينبغي مقارنة أكثر من طريقة أو نموذج عند اتخاذ قرارات حساسة للمخاطر."},{"type":"text","text":"مثال: تصغير الهطول في منطقة جبلية يحتاج تمثيل الارتفاع واتجاه السفوح والتحقق من السجلات المطرية."},{"type":"callout","text":"خلاصة: التصغير يضيف تفاصيل مكانية، لكنه لا يضمن دقة أعلى دون تقييم مستقل."}]}',2090,60,'["تمييز أنواع التصغير","فهم التصغير الديناميكي والإحصائي","تقييم ملاءمة البيانات المحلية"]','إسقاطات المناخ ومعالجتها'),
('climate-projection-bias-adjustment','تصحيح انحياز الإسقاطات المناخية','مقارنة الفترة التاريخية وضبط التوزيعات وتقييم أثر التصحيح.','{"blocks":[{"type":"text","text":"قد تختلف مخرجات النموذج المناخي عن الرصد التاريخي بسبب الانحيازات في المتوسط أو التباين أو التوزيع."},{"type":"text","text":"يهدف تصحيح الانحياز إلى تعديل المخرجات لتصبح أكثر اتساقاً إحصائياً مع فترة مرجعية مرصودة."},{"type":"text","text":"تستخدم طرق بسيطة لتصحيح المتوسط، وطرق أخرى لتعديل التوزيع الكامل للمتغير."},{"type":"text","text":"يجب اختيار فترة مرجعية متجانسة وبيانات رصد مناسبة مكانياً وزمنياً."},{"type":"text","text":"قد يؤثر التصحيح في اتجاهات التغير المستقبلية إذا لم يحافظ على الإشارة المناخية للنموذج."},{"type":"text","text":"تحتاج المتغيرات المتعددة إلى معالجة متسقة حتى لا تتعارض العلاقات الفيزيائية بينها."},{"type":"text","text":"قد يؤدي التصحيح المفرط إلى تغيير القيم المتطرفة أو إنشاء خصائص غير ممثلة في النموذج الأصلي."},{"type":"text","text":"ينبغي مقارنة التوزيعات قبل التصحيح وبعده والتحقق من الاتجاهات والتطرفات."},{"type":"text","text":"لا يعالج تصحيح الانحياز أخطاء العمليات الفيزيائية أو السيناريوهات أو عدم اليقين البنيوي."},{"type":"text","text":"يجب توثيق الطريقة والفترة المرجعية ومجال التطبيق والقيود."},{"type":"text","text":"مثال: تصحيح متوسط الحرارة لا يضمن أن النموذج أصبح قادراً على تمثيل موجات الحر القصوى."},{"type":"callout","text":"خلاصة: تصحيح الانحياز خطوة معالجة إحصائية تحتاج تحققاً يحافظ على المعنى المناخي للإسقاط."}]}',2100,60,'["شرح الانحياز المناخي","تمييز التصحيح الإحصائي عن التصغير","فهم أثر التصحيح على التطرفات"]','إسقاطات المناخ ومعالجتها'),
('climate-model-evaluation-and-selection','تقييم النماذج المناخية واختيارها للدراسات الإقليمية','مقارنة المحاكاة التاريخية والمهارة والاتساق وعدم اليقين بين النماذج.','{"blocks":[{"type":"text","text":"يهدف تقييم النماذج المناخية إلى معرفة مدى قدرتها على تمثيل الخصائص المناخية المهمة للمنطقة والمتغير المستهدف."},{"type":"text","text":"تستخدم المحاكاة التاريخية للمقارنة مع سجلات الرصد خلال فترة مشتركة مناسبة."},{"type":"text","text":"تشمل معايير التقييم المتوسطات والموسمية والتباين والاتجاهات والتطرفات والأنماط المكانية."},{"type":"text","text":"قد ينجح النموذج في تمثيل متوسط الحرارة لكنه يواجه صعوبة في تمثيل الهطول المتطرف أو التوزيع الموسمي."},{"type":"text","text":"تختلف مهارة النماذج بحسب المنطقة والموسم والمتغير والمقياس المكاني."},{"type":"text","text":"تساعد مجموعات النماذج في وصف نطاق النتائج وعدم اليقين البنيوي."},{"type":"text","text":"لا يعني اختيار النموذج الأقرب تاريخياً أنه سيكون الأفضل في المستقبل؛ إذ تتغير الظروف والعمليات."},{"type":"text","text":"قد يؤدي اختيار عدد قليل من النماذج المتشابهة إلى تقليل التنوع الحقيقي في المجموعة."},{"type":"text","text":"ينبغي توثيق معايير الاختيار والأوزان ومصادر البيانات المرجعية."},{"type":"text","text":"تستخدم نتائج التقييم لتحديد الاستخدام المناسب للنماذج بدلاً من ترتيب مطلق يصلح لكل التطبيقات."},{"type":"text","text":"مثال: دراسة موارد المياه تحتاج إعطاء وزن خاص لموسمية الهطول والتطرفات، لا لمتوسط الحرارة فقط."},{"type":"callout","text":"خلاصة: اختيار النماذج قرار مرتبط بالسؤال العلمي والمتغير والمنطقة وليس بمقياس واحد."}]}',2110,60,'["تحديد معايير تقييم النماذج","مقارنة المحاكاة بالرصد","فهم مجموعة النماذج"]','إسقاطات المناخ ومعالجتها'),
('climate-scenarios-and-regional-applications','السيناريوهات المناخية وتطبيقاتها الإقليمية','استخدام مسارات الانبعاثات والسيناريوهات الاجتماعية والاقتصادية في التخطيط.','{"blocks":[{"type":"text","text":"السيناريو المناخي وصف مشروط لمسار محتمل للانبعاثات والتطور الاجتماعي والاقتصادي وليس توقعاً مؤكداً لما سيحدث."},{"type":"text","text":"تستخدم أطر SSP مسارات اجتماعية واقتصادية مشتركة لدراسة تطورات مختلفة في السكان والطاقة والتنمية والسياسات."},{"type":"text","text":"ترتبط السيناريوهات بمستويات مختلفة من التركيزات والتأثير الإشعاعي في نهاية المطاف."},{"type":"text","text":"تستخدم النماذج المناخية السيناريوهات لتقدير نطاقات الاستجابة المناخية المستقبلية."},{"type":"text","text":"لا يمثل السيناريو احتمالاً إحصائياً بحد ذاته، ولا ينبغي تفسيره على أنه المسار الأكثر ترجيحاً دون أساس."},{"type":"text","text":"تختلف آثار السيناريوهات مع الفترة الزمنية والمنطقة والمتغير المناخي."},{"type":"text","text":"تستخدم الإسقاطات في التخطيط للمياه والزراعة والصحة والطاقة والبنية التحتية."},{"type":"text","text":"يجب ذكر السيناريو والفترة المرجعية وفترة الإسقاط ومجموعة النماذج وطريقة التصغير."},{"type":"text","text":"قد تكون الفروق بين السيناريوهات أصغر من عدم اليقين الطبيعي في الفترات القريبة لبعض المتغيرات."},{"type":"text","text":"تساعد مقارنة عدة سيناريوهات على اختبار متانة الخطط أمام مستقبلات مختلفة."},{"type":"text","text":"مثال: تخطيط خزان مائي طويل الأمد يمكن أن يختبر الأداء تحت سيناريوهات متعددة للهطول والطلب والحرارة."},{"type":"callout","text":"خلاصة: السيناريوهات أدوات تخطيط مشروط، ويجب عرضها مع عدم اليقين وحدودها."}]}',2120,60,'["تمييز السيناريو عن التنبؤ","شرح مسارات SSP","اختيار سيناريو مناسب للدراسة"]','إسقاطات المناخ ومعالجتها'),
('climate-adaptation-pathways-and-planning','مسارات التكيف المناخي والتخطيط طويل الأمد','اختيار إجراءات مرنة ومراحل تنفيذ ومؤشرات متابعة في ظل عدم اليقين.','{"blocks":[{"type":"text","text":"مسارات التكيف مجموعة إجراءات متتابعة يمكن تعديلها مع تغير المناخ والمعرفة والاحتياجات."},{"type":"text","text":"تبدأ عملية التخطيط بتحديد الأهداف والقطاعات والأنظمة الحساسة ومجالات المخاطر."},{"type":"text","text":"تحدد خيارات التكيف بحسب الفاعلية والتكلفة والعدالة والآثار الجانبية وإمكانية التنفيذ."},{"type":"text","text":"قد تشمل الإجراءات تحسين إدارة المياه وتطوير الرصد وتعديل معايير التصميم وتحسين التخطيط الحضري والزراعي."},{"type":"text","text":"تستخدم السيناريوهات المتعددة لاختبار أداء الإجراء تحت مستقبلات مناخية مختلفة."},{"type":"text","text":"تحدد نقاط التحول أو العتبات التي يصبح عندها الإجراء الحالي غير كافٍ أو يحتاج إلى تحديث."},{"type":"text","text":"يساعد التخطيط المرحلي على تجنب الاستثمار غير المرن عندما يكون عدم اليقين مرتفعاً."},{"type":"text","text":"تحتاج إجراءات التكيف إلى مؤشرات متابعة تقيس التنفيذ والنتائج والآثار الجانبية."},{"type":"text","text":"قد يؤدي التكيف غير المدروس إلى نقل المخاطر إلى مناطق أو فئات أخرى، وهو ما يعرف بسوء التكيف."},{"type":"text","text":"تتطلب الخطط مشاركة الجهات المعنية والمجتمعات وتحديد المسؤوليات والتمويل."},{"type":"text","text":"مثال: يمكن تنفيذ تحسينات كفاءة المياه أولاً، مع تحديد مؤشرات تستدعي توسيع التخزين أو تنويع المصادر لاحقاً."},{"type":"callout","text":"خلاصة: التكيف الفعال مسار مرن قابل للمراجعة والتعلم وليس إجراءً منفرداً ثابتاً."}]}',2130,60,'["شرح مفهوم مسارات التكيف","تمييز الإجراءات قصيرة وطويلة الأمد","فهم نقاط التحول التخطيطية"]','التكيف والقرار المناخي'),
('climate-risk-in-water-and-agriculture','مخاطر المناخ في المياه والزراعة والتخطيط القطاعي','دمج الإسقاطات المناخية مع نماذج الأحواض والمحاصيل والطلب المستقبلي.','{"blocks":[{"type":"text","text":"تتأثر الزراعة والمياه بتغير الحرارة والهطول والتبخر-النتح وتوقيت المواسم والتطرفات."},{"type":"text","text":"تحتاج دراسة القطاع الزراعي إلى معلومات عن المحاصيل ومواعيد الزراعة والتربة والري وحساسية مراحل النمو."},{"type":"text","text":"تحتاج دراسة الموارد المائية إلى بيانات الأحواض والتدفقات والتخزين والطلب والبنية التحتية."},{"type":"text","text":"تستخدم الإسقاطات المناخية كمدخلات لنماذج المحاصيل والهيدرولوجيا بعد التحقق والتصغير والمعالجة المناسبة."},{"type":"text","text":"يجب فصل أثر تغير المناخ عن أثر تغير استخدام الأرض والسحب المائي والتقنيات والسياسات."},{"type":"text","text":"تؤثر الافتراضات الاجتماعية والاقتصادية في الطلب المستقبلي على المياه والغذاء والطاقة."},{"type":"text","text":"تستخدم السيناريوهات المتعددة لتحديد مدى متانة الخيارات القطاعية أمام تغير المناخ."},{"type":"text","text":"قد تكون النتائج حساسة لطريقة التصغير وتصحيح الانحياز واختيار النموذج والنطاق الزمني."},{"type":"text","text":"ينبغي عرض النتائج كنطاقات واحتمالات عند وجود عدم يقين مرتفع بدلاً من أرقام قطعية."},{"type":"text","text":"تساعد المؤشرات القطاعية في متابعة أثر إجراءات التكيف وتحديد الحاجة إلى تحديث الخطط."},{"type":"text","text":"مثال: تقدير الاحتياج المائي المستقبلي يحتاج ربط تغير ET0 بتغير نوع المحصول والمساحة وكفاءة الري ومصادر المياه."},{"type":"callout","text":"خلاصة: التخطيط القطاعي المناخي يتطلب دمج المناخ مع قرارات الإدارة والطلب والموارد."}]}',2140,60,'["ربط الإسقاطات بالقطاعات","تمييز أثر المناخ عن أثر الإدارة","بناء تحليل سيناريوهات قطاعي"]','التكيف والقرار المناخي'),
('climate-communication-and-decision-support','التواصل المناخي ودعم القرار للجهات المستفيدة','تحويل الإسقاطات والمخاطر إلى معلومات مفهومة قابلة للاستخدام.','{"blocks":[{"type":"text","text":"يهدف التواصل المناخي إلى تحويل البيانات والتحليلات إلى معلومات تساعد الجهات على اتخاذ قرارات طويلة الأمد."},{"type":"text","text":"يجب تحديد المستخدم والقرار والمهلة الزمنية والمقياس المكاني قبل تصميم المنتج المناخي."},{"type":"text","text":"تختلف احتياجات قطاع المياه عن الزراعة والصحة والطاقة والتخطيط العمراني."},{"type":"text","text":"ينبغي التمييز بين الطقس والتوقع الموسمي والإسقاط المناخي والسيناريو المشروط."},{"type":"text","text":"يجب شرح الاحتمالات وعدم اليقين والفترة المرجعية والسيناريو والنماذج المستخدمة."},{"type":"text","text":"تساعد الخرائط والرسوم والملخصات التنفيذية على عرض المعلومات دون إخفاء القيود العلمية."},{"type":"text","text":"ينبغي تجنب عرض متوسطات إقليمية على أنها تمثل كل المواقع أو الفئات السكانية."},{"type":"text","text":"تتطلب المنتجات التفاعلية بيانات وصفية ومصادر موثقة وتاريخ تحديث واضح."},{"type":"text","text":"يساعد الحوار مع المستخدمين على معرفة ما إذا كانت المعلومات مفهومة وقابلة للتطبيق."},{"type":"text","text":"تراجع فاعلية التواصل عبر قياس الاستخدام والفهم والتأثير في القرار وليس عدد مرات نشر المنتج فقط."},{"type":"text","text":"مثال: خريطة تغير الهطول تحتاج شرح السيناريو والفترة المرجعية ونطاق النماذج حتى لا تفسر كجدول توقع يومي."},{"type":"callout","text":"خلاصة: التواصل المناخي الجيد يربط العلم بالقرار ويعرض عدم اليقين بوضوح ومسؤولية."}]}',2150,60,'["صياغة رسالة مناخية واضحة","شرح الاحتمالات وعدم اليقين","مواءمة المنتج مع القرار"]','التكيف والقرار المناخي'))
insert into public.academy_lessons(course_id,chapter_id,unit_id,slug,title,summary,content,published,sort_order,level,estimated_minutes,learning_objectives,chapter_title,unit_title)
select c.id,ch.id,case d.unit when 'تقييم المخاطر المناخية' then u1.id when 'إسقاطات المناخ ومعالجتها' then u2.id when 'التكيف والقرار المناخي' then u3.id end,d.slug,d.title,d.summary,d.content::jsonb,false,d.ord,'advanced',d.mins,d.objectives::jsonb,'تغير المناخ وتقييم المخاطر والتكيف القطاعي',d.unit from d cross join c cross join ch cross join u1 cross join u2 cross join u3
on conflict(course_id,slug) do update set chapter_id=excluded.chapter_id,unit_id=excluded.unit_id,title=excluded.title,summary=excluded.summary,content=excluded.content,published=false,sort_order=excluded.sort_order,level=excluded.level,estimated_minutes=excluded.estimated_minutes,learning_objectives=excluded.learning_objectives,chapter_title=excluded.chapter_title,unit_title=excluded.unit_title;